SELECT * FROM vectors;
-- _________for cosine similarity________ 
SELECT id , 1 - (embedding <=> '[1,2,3,4,3]') AS smilarity_score 
FROM vectors 
ORDER BY embedding <=> '[1,2,3,4,3]'
LIMIT 2;

-- _____________ for euclidean distance ___________ 

EXPLAIN analyze 
SELECT id , 1 - (embedding <-> '[1,2,3,4,3]') AS smilarity_score 
FROM vectors 
ORDER BY embedding <#> '[1,2,3,4,3]'
LIMIT 3;